-- This file contains configuration from Hyprdots that I currently have disabled.
-- They are left here for reference, in case they may prove useful in the future.

--# From keybindings.conf

-- Trigger when the switch is turning off
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("switch:on:Lid Switch", hl.dsp.exec_cmd("swaylock && systemctl suspend"), { locked = true })

-- Exec custom scripts
hl.bind(mainMod .. " + ALT + G", hl.dsp.exec_cmd("~/.config/hypr/scripts/gamemode.sh"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("~/.config/hypr/scripts/wallbashtoggle.sh"))

--# From userprefs.conf:

-- █▀▀ █▄░█ █░█
-- ██▄ █░▀█ ▀▄▀

hl.env("GDK_SCALE", "1")

hl.bind(CONTROL .. " + ALT + SHIFT + R", hl.dsp.pass({ window = "^(com\\.obsproject\\.Studio)$" }))
hl.bind(mainMod .. " + SHIFT + G", hl.dsp.exec_cmd("pkill -x rofi || ~/.config/hypr/scripts/gamelauncher.sh 3"))
hl.bind(mainMod .. " + period", hl.dsp.exec_cmd("emote"))
hl.bind(mainMod .. " + ALT + XF86MonBrightnessDown", hl.dsp.exec_cmd("hyprshade on blue-light-filter"))
hl.bind(mainMod .. " + ALT + XF86MonBrightnessUp", hl.dsp.exec_cmd("hyprshade off"))

hl.window_rule({
    match = {
        class = "^(Steam)$",
    },
    opacity = "0.60 0.60",
})

hl.window_rule({
    match = {
        class = "^(steam)$",
    },
    opacity = "0.60 0.60",
})

hl.window_rule({
    match = {
        class = "^(steamwebhelper)$",
    },
    opacity = "0.60 0.60",
})

hl.window_rule({
    match = {
        class = "^(Spotify)$",
    },
    opacity = "0.60 0.60",
})

hl.bind("CTRL + Alt_L + V", hl.dsp.submap("passthrough"))
hl.define_submap("passthrough", function()
    hl.bind("CTRL + Alt_L + V", hl.dsp.submap("reset"))
end)

hl.config({
